import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as a,a as e}from"./app-b538be9d.js";const t={},o=e(`<h1 id="query-expressions" tabindex="-1"><a class="header-anchor" href="#query-expressions" aria-hidden="true">#</a> Query Expressions</h1><div class="hint-container note"><p class="hint-container-title">Röviden</p><p>A <strong>Query Expressions</strong> egy speciális típusú utasítás, amely lehetővé teszi, hogy egy adatgyűjteményből bizonyos darabokat kivonjunk és egy másik formátumban vagy szervezésben visszaadjuk azt.</p><ul><li>A <strong>from</strong> azonosítja a lekérdezett gyűjteményt.</li><li>A <strong>select</strong> azonosítja az előállítandó adatokat.</li><li>A <strong>where</strong> kiszűri a lekérdezés elemeit.</li><li><strong>orderby</strong> az eredményeket rendezi.</li><li><strong>join</strong> több gyűjteményt egyesít.</li><li><strong>let</strong> lehetővé teszi, hogy a lekérdezés egy részének nevet adjon a későbbi hivatkozáshoz.</li><li><strong>group</strong> az adatokat csoportokba sorolja.</li></ul></div><p>A legtöbb program adatgyűjteményekkel dolgozik és szükségük van az adatok keresésére. Ezeket a feladattípusokat <strong>lekérdezésnek</strong> nevezzük. Íme néhány példa:</p><ul><li>Az ingatlanpiacon keressük meg az összes olyan házat, amely 400 000 dollár alatt van és legalább 2 fürdőszobával és 3 hálószobával rendelkezik.</li><li>Egy projektben találjuk meg az összes aktív feladatot, amelyet egy csapat tagjaihoz rendeltek.</li><li>Egy videojátékban keressük meg az összes olyan objektumot, amely elég közel van egy robbanáshoz ahhoz, hogy sérülést szenvedjen.</li></ul><p>A <strong>C#</strong> nyelvben olyan kifejezést használunk, amely a lekérdezések könnyűvé tételére szolgál. Ezeket a kifejezéseket <strong>Language Integrated Queries (LINQ)</strong>-nak vagy egyszerűen <strong>lekérdezési kifejezéseknek</strong> nevezzük. Ezek a lekérdezési kifejezések leggyakrabban memóriában lévő objektumokon (tömbökön, listákon, szótárakon stb.) hajtódnak végre. De a <strong>LINQ</strong> lehetővé teszi, hogy egy lekérdezés adatokat szerezzen be egy valós adatbázisból, például <strong>MySQL</strong>, <strong>Oracle</strong> vagy <strong>Microsoft SQL Server</strong>-ből. Az elsőt <strong>LINQ for Objects</strong>-nek, a másodikat pedig <strong>LINQ for SQL</strong>-nek nevezzük.</p><div class="hint-container warning"><p class="hint-container-title">Mi most a memóriában lévő objektumok lekérdezésére fogunk összpontosítani.</p></div><p>Bármit, amit <strong>Query Expression</strong>-nel (<em>lekérdezési kifejezésekkel</em>) teszünk, elvégezhettük volna <strong>if utasításokkal</strong> és <strong>ciklusokkal</strong> is. De ahogy látni fogjuk, a <strong>Query Expression</strong>-nel (<em>lekérdezési kifejezésekkel</em>) gyakran olvashatóbbak és rövidebbek.</p><h2 id="lekerdezesek-es-ienumerable-t" tabindex="-1"><a class="header-anchor" href="#lekerdezesek-es-ienumerable-t" aria-hidden="true">#</a> Lekérdezések és <code>IEnumerable&lt;T&gt;</code></h2><p>A lekérdezési kifejezések olyan objektumokon működnek, amelyek megvalósítják az <code>IEnumerable&lt;T&gt;</code> interfészt. Ez gyakorlatilag minden gyűjtemény típusra vonatkozik a <strong>.NET keretrendszerben</strong>, beleértve a listákat, tömböket és szótárakat is.</p><p>A <code>System.Linq.Enumerable</code> osztály határozza meg ezeket a kiterjesztési metódusokat. A <strong>.NET 6</strong> projektekben van egy implicit <strong>using</strong> direktíva a <strong>System.Linq</strong> névtérre, de ha régebbi verziót használnánk, akkor manuálisan kellene hozzá adnunk a <code>using System.Linq;</code> sort a fájljainkhoz.</p><h2 id="minta-osztalyok" tabindex="-1"><a class="header-anchor" href="#minta-osztalyok" aria-hidden="true">#</a> Minta osztályok</h2><p>Az alábbi három osztályt fogjuk használni a példákban. A <code>GameObject</code> osztály a játékban található potenciálisan sokféle objektum alapja és a <code>Ship</code> egy ilyen típus. A <code>Player</code> osztály egy játékos reprezentálására szolgál és a <code>GameObject</code> példányok mindegyike egy játékos tulajdonában van.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">GameObject</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">int</span></span> ID <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">double</span></span> X <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">double</span></span> Y <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">int</span></span> MaxHP <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">int</span></span> HP <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">int</span></span> PlayerID <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Ship</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">GameObject</span></span> <span class="token punctuation">{</span> <span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">record</span> <span class="token class-name">Player</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">int</span></span> ID<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> UserName<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> TeamColor<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Pár példa:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">List<span class="token punctuation">&lt;</span>GameObject<span class="token punctuation">&gt;</span></span> objects <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">List<span class="token punctuation">&lt;</span>GameObject<span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Ship</span> <span class="token punctuation">{</span> ID <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span> X<span class="token operator">=</span><span class="token number">0</span><span class="token punctuation">,</span> Y<span class="token operator">=</span><span class="token number">0</span><span class="token punctuation">,</span> HP <span class="token operator">=</span> <span class="token number">50</span><span class="token punctuation">,</span> MaxHP <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">,</span> PlayerID <span class="token operator">=</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Ship</span> <span class="token punctuation">{</span> ID <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">,</span> X<span class="token operator">=</span><span class="token number">4</span><span class="token punctuation">,</span> Y<span class="token operator">=</span><span class="token number">2</span><span class="token punctuation">,</span> HP <span class="token operator">=</span> <span class="token number">75</span><span class="token punctuation">,</span> MaxHP <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">,</span> PlayerID <span class="token operator">=</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Ship</span> <span class="token punctuation">{</span> ID <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> X<span class="token operator">=</span><span class="token number">9</span><span class="token punctuation">,</span> Y<span class="token operator">=</span><span class="token number">3</span><span class="token punctuation">,</span> HP <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> MaxHP <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">,</span> PlayerID <span class="token operator">=</span> <span class="token number">2</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token class-name">List<span class="token punctuation">&lt;</span>Player<span class="token punctuation">&gt;</span></span> players <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">List<span class="token punctuation">&lt;</span>Player<span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Player</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string">&quot;Player 1&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Red&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> 
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Player</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token string">&quot;Player 2&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Blue&quot;</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="query-expressions-alapok" tabindex="-1"><a class="header-anchor" href="#query-expressions-alapok" aria-hidden="true">#</a> Query Expressions alapok</h2><p>A <strong>Query Expressions</strong> kisebb elemekből állnak, amelyeket feltételeknek nevezünk. Minden feltétel olyan, mint egy állomás egy összeszerelő sorban. Az előző feltételtől kap elemeket, majd az utána következő feltételt látja el elemekkel. Új feltételeket adhatunk hozzá, hogy elérjük a kívánt eredményt. A <strong>Query Expressions</strong> a <strong>from</strong>-al kezdődnek és a <strong>select</strong>-el fejeződnek be. A <strong>from</strong> az adatforrást azonosítja. A <strong>select</strong> pedig azt mutatja meg, hogy mely részét szeretnénk az adatnak eredményként előállítani. A legegyszerűbb <strong>Query Expression</strong> így néz ki:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">IEnumerable<span class="token punctuation">&lt;</span>GameObject<span class="token punctuation">&gt;</span></span> everything <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Az eredmény egy <code>IEnumerable&lt;GameObject&gt;</code>, nem pedig egy <code>List&lt;GameObject&gt;</code>. A <strong>Query Expression</strong>-ek <code>IEnumerable&lt;T&gt;</code> típust eredményeznek.</p><ol><li><p>A <code>from</code> az első sor: <code>from o in objects</code>. A <code>from</code> a lekérdezést azzal kezdi, hogy megnevezi a forrását: <code>objects</code>.</p></li><li><p>A select a második sor: <code>select o</code>. A <code>select</code>, amely kiszámítja a lekérdezés végső eredményét, az <code>objects</code>-ből.</p></li></ol><p>Próbáljunk meg ezt ami most az objektumok azonosítóját kapja meg, a teljes objektum helyett:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> ids <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects <span class="token keyword">select</span> o<span class="token punctuation">.</span>ID<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Az eredmény egy <code>IEnumerable&lt;int&gt;</code>, nem pedig <code>IEnumerable&lt;GameObject&gt;</code>, mivel a <code>select</code> kifejezése egy <code>int</code>-et eredményezett. De a <code>select</code> kifejezésébe bármit beilleszthetünk.</p><p>Például:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> healthText <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects <span class="token keyword">select</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">o<span class="token punctuation">.</span>HP</span><span class="token punctuation">}</span></span><span class="token string">/</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">o<span class="token punctuation">.</span>MaxHP</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Ez a lekérdezés minden játékobjektumhoz egy szöveget ad, például &quot;<strong>0/50</strong>&quot; vagy &quot;<strong>92/100</strong>&quot;.</p><p>Mit szólsz ehhez?</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> healthStatus <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects <span class="token keyword">select</span> <span class="token punctuation">(</span>o<span class="token punctuation">,</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">o<span class="token punctuation">.</span>HP</span><span class="token punctuation">}</span></span><span class="token string">/</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">o<span class="token punctuation">.</span>MaxHP</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Tuple</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Ez a lekérdezés létrehoz egy <strong>tuple</strong>-t, amely az eredeti objektumot és egészségi állapotára vonatkozó szövegét kombinálja. A <code>healthStatus</code> típusa <code>IEnumerable&lt;(GameObject, string)&gt;</code>. A <strong>Query Expression</strong>-nel könnyen készíthetünk furcsa, összetett típusokat rövid távú használatra.</p><h3 id="szures" tabindex="-1"><a class="header-anchor" href="#szures" aria-hidden="true">#</a> Szűrés</h3><p>A <code>where</code> egy olyan kifejezést ad, amely az elemek szűrésére szolgál. Tartalmaz egy kifejezést, amelynek igaznak kell lennie ahhoz, hogy az elem megfeleljen a szűrésnek. A következő kifejezés csak olyan játékobjektumokat eredményez, amelyeknek az életerő tulajdonsága nagyobb, mint 0.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> aliveObjects <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects <span class="token keyword">where</span> <span class="token class-name">o</span><span class="token punctuation">.</span>HP <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Összetetté is tehetjünk az alábbiakban több <code>where</code> záradékot alkalmazunk egymás után:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> aliveObjects <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                   <span class="token keyword">where</span> <span class="token class-name">o</span><span class="token punctuation">.</span>PlayerID <span class="token operator">==</span> <span class="token number">4</span>
                   <span class="token keyword">where</span> <span class="token class-name">o</span><span class="token punctuation">.</span>HP <span class="token operator">&gt;</span> <span class="token number">0</span>
                   <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="rendezes" tabindex="-1"><a class="header-anchor" href="#rendezes" aria-hidden="true">#</a> Rendezés</h3><p>Az <code>orderby</code> elemeket rendez. Ebben a kódban egy <code>IEnumerable&lt;GameObject&gt;</code>-t hoz létre, ahol az első elem a legalacsonyabb <strong>MaxHP</strong>-val rendelkezik, majd a következő legalacsonyabb és így tovább.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> weakestObjects <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                     <span class="token keyword">orderby</span> o<span class="token punctuation">.</span>MaxHP
                     <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Megfordíthatjuk a sorrendet, ha a csökkenő kulcsszót a végére tesszük:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> strongestObjects <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                     <span class="token keyword">orderby</span> o<span class="token punctuation">.</span>MaxHP <span class="token keyword">descending</span>
                     <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container info"><p class="hint-container-title">Az ascending kulcsszó is használható, de ez az alapértelmezett, így általában nincs szükség.</p></div><p>Ha egy döntetlen helyzetet kell megoldani, több kifejezést is megadhatunk a rendezéshez, vesszővel elválasztva:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> weakestObjects <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                     <span class="token keyword">orderby</span> o<span class="token punctuation">.</span>MaxHP<span class="token punctuation">,</span> o<span class="token punctuation">.</span>HP
                     <span class="token keyword">select</span> o<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ez a rendezés elsősorban a <code>MaxHP</code> alapján történik, de a döntetlen helyzeteket a <code>HP</code> alapján oldja meg. Tetszőleges számú rendezési szempontot megadhatunk, vesszővel elválasztva.</p><h2 id="metodushivasos-szintaxis" tabindex="-1"><a class="header-anchor" href="#metodushivasos-szintaxis" aria-hidden="true">#</a> Metódushívásos szintaxis</h2><p>Ha nem szeretjük az új kulcsszavakat, akkor szerencsénk van. Minden <strong>Query Expression</strong> -t megírhatjuk metódushívásokkal a kulcsszavak helyett. Ahol a <code>where</code> kulcsszó áll, ott a <code>Where</code> metódust használjuk. A <code>select</code> kulcsszó helyett pedig a <code>Select</code> metódust alkalmazunk. Tekintsük meg ezt a lekérdezést:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> results <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
              <span class="token keyword">where</span> <span class="token class-name">o</span><span class="token punctuation">.</span>HP <span class="token operator">&gt;</span> <span class="token number">0</span>
              <span class="token keyword">orderby</span> o<span class="token punctuation">.</span>HP
              <span class="token keyword">select</span> o<span class="token punctuation">.</span>HP <span class="token operator">/</span> o<span class="token punctuation">.</span>MaxHP<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A metódushívás szintaxisával ez így nézne ki:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> results <span class="token operator">=</span> objects
                   <span class="token punctuation">.</span><span class="token function">Where</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>HP <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span>
                   <span class="token punctuation">.</span><span class="token function">OrderBy</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>HP<span class="token punctuation">)</span>
                   <span class="token punctuation">.</span><span class="token function">Select</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>HP <span class="token operator">/</span> o<span class="token punctuation">.</span>MaxHP<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ezek a módszerek jellemzően <strong>delegate</strong> paraméterekkel rendelkeznek, ezért gyakoriak a lambda-kifejezések.</p><h2 id="egyedi-metodusok" tabindex="-1"><a class="header-anchor" href="#egyedi-metodusok" aria-hidden="true">#</a> Egyedi metódusok</h2><p>A metódushívás szintaxis mindent meg tud tenni, amit a kulcsszavak is meg tudnak tenni, valamint néhány olyan dolgot is, amire nincsenek kulcsszavak. Íme néhány a leghasznosabb közülük.</p><p>A <code>Count</code> lehetővé teszi, hogy vagy megszámlálja a gyűjtemény összes elemét, vagy azok számát, amelyek egy adott feltételnek megfelelnek:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">int</span></span> totalItems <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">Count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">int</span></span> player1ObjectCount <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">Count</span><span class="token punctuation">(</span>x <span class="token operator">=&gt;</span> x<span class="token punctuation">.</span>PlayerID <span class="token operator">==</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Az <code>Any</code> and <code>All</code> megmondja, hogy a gyűjtemény bármelyik vagy minden eleme megfelel-e valamilyen feltételnek:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">bool</span></span> anyAlive <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">Any</span><span class="token punctuation">(</span>y <span class="token operator">=&gt;</span> y<span class="token punctuation">.</span>HP <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">bool</span></span> allDead <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">All</span><span class="token punctuation">(</span>y <span class="token operator">=&gt;</span> y<span class="token punctuation">.</span>HP <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>A <code>Skip</code> lehetővé teszi, hogy kihagyjon néhány elemet az elején, míg a <code>Take</code> lehetővé teszi, hogy az első néhány elemet megragadja a többit elhagyva:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> allButFirst <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">OrderBy</span><span class="token punctuation">(</span>m <span class="token operator">=&gt;</span> m<span class="token punctuation">.</span>HP<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Skip</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">var</span></span> firstThree <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">OrderBy</span><span class="token punctuation">(</span>m <span class="token operator">=&gt;</span> m<span class="token punctuation">.</span>HP<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Take</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Az <code>Avarage</code>, a <code>Sum</code>, a <code>Min</code> és a <code>Max</code> segítségével matematikai műveleteket végezhetünk az elemekkel:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">int</span></span> longestName          <span class="token operator">=</span> players<span class="token punctuation">.</span><span class="token function">Max</span><span class="token punctuation">(</span>p <span class="token operator">=&gt;</span> p<span class="token punctuation">.</span>UserName<span class="token punctuation">.</span>Length<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">int</span></span> shortestName         <span class="token operator">=</span> players<span class="token punctuation">.</span><span class="token function">Min</span><span class="token punctuation">(</span>p <span class="token operator">=&gt;</span> p<span class="token punctuation">.</span>UserName<span class="token punctuation">.</span>Length<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">double</span></span> averageNameLength <span class="token operator">=</span> players<span class="token punctuation">.</span><span class="token function">Average</span><span class="token punctuation">(</span>p <span class="token operator">=&gt;</span> p<span class="token punctuation">.</span>UserName<span class="token punctuation">.</span>Length<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">int</span></span> totalHP              <span class="token operator">=</span> objects<span class="token punctuation">.</span><span class="token function">Sum</span><span class="token punctuation">(</span>o <span class="token operator">=&gt;</span> o<span class="token punctuation">.</span>HP<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="tobb-gyujtemeny-osszekapcsolasa" tabindex="-1"><a class="header-anchor" href="#tobb-gyujtemeny-osszekapcsolasa" aria-hidden="true">#</a> Több gyűjtemény összekapcsolása</h2><p>Más helyzetekben két gyűjteményt szeretnénk összekapcsolni egy közös kapcsolaton keresztül. Ahelyett, hogy az egyik gyűjtemény minden elemét egy másik gyűjtemény minden elemével párosítva néznénk meg, csak az egymásnak megfelelő párosításokat szeretnénk látni. Az adatbázisok világában ezt nevezik összekapcsolásnak. Példánk osztályaiban a <code>GameObject</code> rendelkezik egy <code>PlayerID</code> tulajdonsággal, amely megfelel a <strong>Player ID</strong> tulajdonságának. Úgy tudjuk meghatározni, hogy egy játékobjektumnak milyen színűnek kell lennie, hogy megkeressük a játékobjektumhoz tartozó játékost és ennek a játékosnak a színét használjuk egy <code>join</code> segítségével:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> objectColors <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                   <span class="token keyword">join</span> p <span class="token keyword">in</span> players <span class="token keyword">on</span> o<span class="token punctuation">.</span>PlayerID equals p<span class="token punctuation">.</span>ID
                   <span class="token keyword">select</span> <span class="token punctuation">(</span>o<span class="token punctuation">,</span> p<span class="token punctuation">.</span>TeamColor<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="a-let-kifejezes" tabindex="-1"><a class="header-anchor" href="#a-let-kifejezes" aria-hidden="true">#</a> A <code>let</code> kifejezés</h2><p>A <code>let</code> kifejezés egy másik változót definiál egy lekérdezésben, amit később használhatunk. Ez a kifejezés kiváló, ha ismétlődően számításokat szeretnénk végezni.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">var</span></span> statuses <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
               <span class="token keyword">let</span> percentHealth <span class="token operator">=</span> o<span class="token punctuation">.</span>HP <span class="token operator">/</span> o<span class="token punctuation">.</span>MaxHP <span class="token operator">*</span> <span class="token number">100</span>
               <span class="token keyword">select</span> <span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">o<span class="token punctuation">.</span>ID</span><span class="token punctuation">}</span></span><span class="token string"> is at </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">percentHealth</span><span class="token punctuation">}</span></span><span class="token string">%.&quot;</span></span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="csoportositas" tabindex="-1"><a class="header-anchor" href="#csoportositas" aria-hidden="true">#</a> Csoportosítás</h2><p>A <code>group by</code> kifejezés csoportokba rendezi az elemeket. Az alábbiakban az összes objektumot a tulajdonos játékosuk szerint csoportosítjuk.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">IEnumerable<span class="token punctuation">&lt;</span>IGrouping<span class="token punctuation">&lt;</span><span class="token keyword">int</span><span class="token punctuation">,</span> GameObject<span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> groups <span class="token operator">=</span> <span class="token keyword">from</span> o <span class="token keyword">in</span> objects
                                                 <span class="token keyword">group</span> o <span class="token keyword">by</span> o<span class="token punctuation">.</span>PlayerID<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">A return típusra figyelj!</p><p>Az eredmény egy csoportosítások gyűjteménye. Az <code>IGrouping&lt;Tkey, TElement&gt;</code> interfész az <code>IEnumerable&lt;TElement&gt;</code> kibővítésével rendelkezik egy megosztott kulccsal.</p><p>Itt a kulcs a játékos azonosítója és a gyűjteményben található elemek mind a játékoshoz tartozó objektumok lesznek.</p><p>A <code>group by</code> feltétel két kifejezést tartalmaz. Az első (<em>a fenti kódban az <code>o</code></em>) meghatározza a csoportok végső elemeit. A második (<em>a fenti kódban az <code>o.PlayerID</code></em>) meghatározza, hogy mi a kulcs minden csoport esetén.</p></div>`,69),p=[o];function l(c,r){return n(),a("div",null,p)}const u=s(t,[["render",l],["__file","lesson4.html.vue"]]);export{u as default};
